  mcat_required: "Yes, required for acceptance (taken no later than September of application year; valid within 4 years)",
  overview: "JHUSOM provides foundational medical training through its Genes to Society curriculum, emphasizing individualized patient pathophysiology, early longitudinal clinical immersion, and required Scholarly Concentrations spanning basic science to global public health.",
  program_name: "Bloomberg Philanthropies Full Cost of Attendance & Full Tuition Awards",
  program_url: "https://www.hopkinsmedicine.org/som/offices/finaid/applying-for-aid/med-students/faq",
  program_tab_id: 103795729,
