  eligibility: "Admitted MD students evaluated via CSS Profile. Families earning less than $300,000 qualify for full tuition; families earning less than $175,000 qualify for full cost of attendance.",
  funding_amount: "100% free tuition for families earning <$300,000/yr; 100% full cost of attendance (tuition, fees, and living expenses) for families earning <$175,000/yr."
});

await write("tmp://schools_data.json", JSON.stringify(list, null, 2));
console.log("Saved School 2. Total schools in JSON:", list.length);

